diff --git a/uploader/retry.go b/uploader/retry.go
index 3f2a1c9..8be07d4 100644
--- a/uploader/retry.go
+++ b/uploader/retry.go
@@ -18,12 +18,17 @@ func (u *Uploader) send(ctx context.Context, chunk []byte) error {
 	var err error
-	for i := 0; i < 5; i++ {
-		err = u.post(ctx, chunk)
-		if err == nil {
-			return nil
-		}
-		time.Sleep(time.Second)
+	backoff := 250 * time.Millisecond
+	for i := 0; i < 5; i++ {
+		err = u.post(ctx, chunk)
+		if err == nil || !retryable(err) {
+			return err
+		}
+		select {
+		case <-time.After(backoff):
+			backoff *= 2
+		case <-ctx.Done():
+			return ctx.Err()
+		}
 	}
 	return err
 }
